using System;
using Framework.Parameters;
using UnityEngine;

namespace Game.Tests
{
    /// <summary>
    /// ParameterDefinitionの基本機能と境界条件を検証する。
    /// </summary>
    [DisallowMultipleComponent]
    public sealed class ParameterDefinitionTest : MonoBehaviour
    {
        [Header("テスト設定")]
        [SerializeField]
        [Tooltip("開始時にすべてのテストを実行する。")]
        private bool runTestsOnStart = true;

        [Header("テスト結果")]
        [SerializeField]
        [Tooltip("成功したテスト件数。")]
        private int passedCount;

        [SerializeField]
        [Tooltip("失敗したテスト件数。")]
        private int failedCount;

        /// <summary>
        /// テスト用のパラメーター識別子。
        /// </summary>
        private enum TestParameterId
        {
            /// <summary>
            /// 移動速度。
            /// </summary>
            MoveSpeed,

            /// <summary>
            /// 攻撃性。
            /// </summary>
            Aggression
        }

        /// <summary>
        /// 開始時のテスト実行を制御する。
        /// </summary>
        private void Start()
        {
            if (runTestsOnStart)
            {
                RunAllTests();
            }
        }

        /// <summary>
        /// すべてのテストを実行する。
        /// </summary>
        [ContextMenu("すべてのテストを実行")]
        public void RunAllTests()
        {
            passedCount = 0;
            failedCount = 0;

            try
            {
                TestDefinition();
                TestRange();
                TestClamp();
                TestNormalize();
                TestDenormalize();
                TestFixedValue();
                TestIdentifier();
                TestInvalidDefinition();
                TestInvalidInput();
                TestExtremeRange();
            }
            catch (Exception exception)
            {
                failedCount++;
                Debug.LogException(exception, this);
            }

            Debug.Log(
                $"【ParameterDefinition テスト結果】\n" +
                $"成功：{passedCount}\n" +
                $"失敗：{failedCount}\n" +
                (failedCount == 0
                    ? "すべてのテストに成功しました。"
                    : "失敗したテストを確認してください。"),
                this);
        }

        /// <summary>
        /// 標準的なテスト用定義を生成する。
        /// </summary>
        /// <returns>移動速度のパラメーター定義</returns>
        private ParameterDefinition<TestParameterId> CreateDefinition()
        {
            return new ParameterDefinition<TestParameterId>(
                TestParameterId.MoveSpeed,
                5f,
                0f,
                10f);
        }

        /// <summary>
        /// 定義情報が正しく保持されることを検証する。
        /// </summary>
        private void TestDefinition()
        {
            var definition = CreateDefinition();

            bool idPassed =
                definition.Id == TestParameterId.MoveSpeed;
            Debug.Assert(idPassed, "識別子の検証", this);
            Check(idPassed, "識別子の検証");

            bool defaultPassed = definition.DefaultValue == 5f;
            Debug.Assert(defaultPassed, "初期値の検証", this);
            Check(defaultPassed, "初期値の検証");

            bool minPassed = definition.MinValue == 0f;
            Debug.Assert(minPassed, "最小値の検証", this);
            Check(minPassed, "最小値の検証");

            bool maxPassed = definition.MaxValue == 10f;
            Debug.Assert(maxPassed, "最大値の検証", this);
            Check(maxPassed, "最大値の検証");

            bool fixedPassed = !definition.IsFixedValue;
            Debug.Assert(fixedPassed, "通常範囲の検証", this);
            Check(fixedPassed, "通常範囲の検証");
        }

        /// <summary>
        /// 有効範囲の判定を検証する。
        /// </summary>
        private void TestRange()
        {
            var definition = CreateDefinition();

            bool normalPassed = definition.IsInRange(5f);
            Debug.Assert(normalPassed, "範囲内の判定", this);
            Check(normalPassed, "範囲内の判定");

            bool minPassed = definition.IsInRange(0f);
            Debug.Assert(minPassed, "下限境界の判定", this);
            Check(minPassed, "下限境界の判定");

            bool maxPassed = definition.IsInRange(10f);
            Debug.Assert(maxPassed, "上限境界の判定", this);
            Check(maxPassed, "上限境界の判定");

            bool belowPassed = !definition.IsInRange(-1f);
            Debug.Assert(belowPassed, "下限未満の判定", this);
            Check(belowPassed, "下限未満の判定");

            bool abovePassed = !definition.IsInRange(11f);
            Debug.Assert(abovePassed, "上限超過の判定", this);
            Check(abovePassed, "上限超過の判定");

            bool nanPassed = !definition.IsInRange(float.NaN);
            Debug.Assert(nanPassed, "NaNの判定", this);
            Check(nanPassed, "NaNの判定");

            bool infinityPassed =
                !definition.IsInRange(float.PositiveInfinity);
            Debug.Assert(infinityPassed, "無限大の判定", this);
            Check(infinityPassed, "無限大の判定");
        }

        /// <summary>
        /// 値の範囲制限を検証する。
        /// </summary>
        private void TestClamp()
        {
            var definition = CreateDefinition();

            bool normalPassed = definition.Clamp(5f) == 5f;
            Debug.Assert(normalPassed, "範囲内の制限", this);
            Check(normalPassed, "範囲内の制限");

            bool belowPassed = definition.Clamp(-5f) == 0f;
            Debug.Assert(belowPassed, "下限への制限", this);
            Check(belowPassed, "下限への制限");

            bool abovePassed = definition.Clamp(15f) == 10f;
            Debug.Assert(abovePassed, "上限への制限", this);
            Check(abovePassed, "上限への制限");

            bool minPassed = definition.Clamp(0f) == 0f;
            Debug.Assert(minPassed, "下限値の維持", this);
            Check(minPassed, "下限値の維持");

            bool maxPassed = definition.Clamp(10f) == 10f;
            Debug.Assert(maxPassed, "上限値の維持", this);
            Check(maxPassed, "上限値の維持");
        }

        /// <summary>
        /// パラメーターの正規化を検証する。
        /// </summary>
        private void TestNormalize()
        {
            var definition = CreateDefinition();

            bool centerPassed =
                Mathf.Approximately(definition.Normalize(5f), 0.5f);
            Debug.Assert(centerPassed, "中央値の正規化", this);
            Check(centerPassed, "中央値の正規化");

            bool minPassed = definition.Normalize(0f) == 0f;
            Debug.Assert(minPassed, "最小値の正規化", this);
            Check(minPassed, "最小値の正規化");

            bool maxPassed = definition.Normalize(10f) == 1f;
            Debug.Assert(maxPassed, "最大値の正規化", this);
            Check(maxPassed, "最大値の正規化");

            bool belowPassed = definition.Normalize(-5f) == 0f;
            Debug.Assert(belowPassed, "下限未満の正規化", this);
            Check(belowPassed, "下限未満の正規化");

            bool abovePassed = definition.Normalize(15f) == 1f;
            Debug.Assert(abovePassed, "上限超過の正規化", this);
            Check(abovePassed, "上限超過の正規化");

            var signedDefinition =
                new ParameterDefinition<string>("Signed", 0f, -10f, 10f);

            bool signedPassed =
                Mathf.Approximately(
                    signedDefinition.Normalize(0f),
                    0.5f);
            Debug.Assert(signedPassed, "負数を含む正規化", this);
            Check(signedPassed, "負数を含む正規化");
        }

        /// <summary>
        /// 正規化値から実際の値への変換を検証する。
        /// </summary>
        private void TestDenormalize()
        {
            var definition = CreateDefinition();

            bool centerPassed =
                Mathf.Approximately(definition.Denormalize(0.5f), 5f);
            Debug.Assert(centerPassed, "中央値への変換", this);
            Check(centerPassed, "中央値への変換");

            bool minPassed = definition.Denormalize(0f) == 0f;
            Debug.Assert(minPassed, "最小値への変換", this);
            Check(minPassed, "最小値への変換");

            bool maxPassed = definition.Denormalize(1f) == 10f;
            Debug.Assert(maxPassed, "最大値への変換", this);
            Check(maxPassed, "最大値への変換");

            bool belowPassed = definition.Denormalize(-1f) == 0f;
            Debug.Assert(belowPassed, "下限未満の変換", this);
            Check(belowPassed, "下限未満の変換");

            bool abovePassed = definition.Denormalize(2f) == 10f;
            Debug.Assert(abovePassed, "上限超過の変換", this);
            Check(abovePassed, "上限超過の変換");
        }

        /// <summary>
        /// 最小値と最大値が等しい定義を検証する。
        /// </summary>
        private void TestFixedValue()
        {
            var definition =
                new ParameterDefinition<string>("Fixed", 5f, 5f, 5f);

            bool fixedPassed = definition.IsFixedValue;
            Debug.Assert(fixedPassed, "固定値の判定", this);
            Check(fixedPassed, "固定値の判定");

            bool clampPassed = definition.Clamp(100f) == 5f;
            Debug.Assert(clampPassed, "固定値への制限", this);
            Check(clampPassed, "固定値への制限");

            bool normalizePassed = definition.Normalize(5f) == 0f;
            Debug.Assert(normalizePassed, "固定値の正規化", this);
            Check(normalizePassed, "固定値の正規化");

            bool denormalizePassed =
                definition.Denormalize(0.8f) == 5f;
            Debug.Assert(denormalizePassed, "固定値への変換", this);
            Check(denormalizePassed, "固定値への変換");
        }

        /// <summary>
        /// 識別子の比較と異なる識別子型への対応を検証する。
        /// </summary>
        private void TestIdentifier()
        {
            var definition = CreateDefinition();

            bool matchPassed =
                definition.MatchesId(TestParameterId.MoveSpeed);
            Debug.Assert(matchPassed, "識別子の一致", this);
            Check(matchPassed, "識別子の一致");

            bool mismatchPassed =
                !definition.MatchesId(TestParameterId.Aggression);
            Debug.Assert(mismatchPassed, "識別子の不一致", this);
            Check(mismatchPassed, "識別子の不一致");

            var stringDefinition =
                new ParameterDefinition<string>(
                    "Aggression", 0.5f, 0f, 1f);

            bool stringPassed =
                stringDefinition.MatchesId("Aggression");
            Debug.Assert(stringPassed, "文字列識別子", this);
            Check(stringPassed, "文字列識別子");
        }

        /// <summary>
        /// 不正な定義が例外によって拒否されることを検証する。
        /// </summary>
        private void TestInvalidDefinition()
        {
            bool nullPassed = Throws<ArgumentNullException>(() =>
            {
                new ParameterDefinition<string>(null, 5f, 0f, 10f);
            });
            Debug.Assert(nullPassed, "null識別子の拒否", this);
            Check(nullPassed, "null識別子の拒否");

            bool rangePassed = Throws<ArgumentException>(() =>
            {
                new ParameterDefinition<string>("Test", 5f, 10f, 0f);
            });
            Debug.Assert(rangePassed, "逆転した範囲の拒否", this);
            Check(rangePassed, "逆転した範囲の拒否");

            bool belowPassed = Throws<ArgumentOutOfRangeException>(() =>
            {
                new ParameterDefinition<string>("Test", -1f, 0f, 10f);
            });
            Debug.Assert(belowPassed, "下限未満の初期値の拒否", this);
            Check(belowPassed, "下限未満の初期値の拒否");

            bool abovePassed = Throws<ArgumentOutOfRangeException>(() =>
            {
                new ParameterDefinition<string>("Test", 11f, 0f, 10f);
            });
            Debug.Assert(abovePassed, "上限超過の初期値の拒否", this);
            Check(abovePassed, "上限超過の初期値の拒否");

            bool nanPassed = Throws<ArgumentOutOfRangeException>(() =>
            {
                new ParameterDefinition<string>(
                    "Test", float.NaN, 0f, 10f);
            });
            Debug.Assert(nanPassed, "NaN初期値の拒否", this);
            Check(nanPassed, "NaN初期値の拒否");

            bool minPassed = Throws<ArgumentOutOfRangeException>(() =>
            {
                new ParameterDefinition<string>(
                    "Test", 5f, float.NegativeInfinity, 10f);
            });
            Debug.Assert(minPassed, "無限大の最小値の拒否", this);
            Check(minPassed, "無限大の最小値の拒否");

            bool maxPassed = Throws<ArgumentOutOfRangeException>(() =>
            {
                new ParameterDefinition<string>(
                    "Test", 5f, 0f, float.PositiveInfinity);
            });
            Debug.Assert(maxPassed, "無限大の最大値の拒否", this);
            Check(maxPassed, "無限大の最大値の拒否");
        }

        /// <summary>
        /// 各変換処理に対する不正な入力値を検証する。
        /// </summary>
        private void TestInvalidInput()
        {
            var definition = CreateDefinition();

            bool clampPassed = Throws<ArgumentOutOfRangeException>(() =>
            {
                definition.Clamp(float.NaN);
            });
            Debug.Assert(clampPassed, "Clampの不正入力", this);
            Check(clampPassed, "Clampの不正入力");

            bool normalizePassed =
                Throws<ArgumentOutOfRangeException>(() =>
                {
                    definition.Normalize(float.PositiveInfinity);
                });
            Debug.Assert(normalizePassed, "Normalizeの不正入力", this);
            Check(normalizePassed, "Normalizeの不正入力");

            bool denormalizePassed =
                Throws<ArgumentOutOfRangeException>(() =>
                {
                    definition.Denormalize(float.NegativeInfinity);
                });
            Debug.Assert(denormalizePassed, "Denormalizeの不正入力", this);
            Check(denormalizePassed, "Denormalizeの不正入力");
        }

        /// <summary>
        /// 極端に広い数値範囲での中間計算を検証する。
        /// </summary>
        private void TestExtremeRange()
        {
            var definition =
                new ParameterDefinition<string>(
                    "Extreme",
                    0f,
                    -float.MaxValue,
                    float.MaxValue);

            bool normalizePassed =
                Mathf.Approximately(definition.Normalize(0f), 0.5f);
            Debug.Assert(normalizePassed, "広範囲の正規化", this);
            Check(normalizePassed, "広範囲の正規化");

            bool denormalizePassed =
                definition.Denormalize(0.5f) == 0f;
            Debug.Assert(denormalizePassed, "広範囲の逆変換", this);
            Check(denormalizePassed, "広範囲の逆変換");
        }

        /// <summary>
        /// 指定された処理が期待する例外を発生させるか検証する。
        /// </summary>
        /// <typeparam name="TException">期待する例外型</typeparam>
        /// <param name="action">検証対象の処理</param>
        /// <returns>期待する例外が発生した場合はtrue</returns>
        private bool Throws<TException>(Action action)
            where TException : Exception
        {
            try
            {
                action();
            }
            catch (Exception exception)
            {
                // 派生型を含めず、期待した例外型との完全一致を確認する。
                if (exception.GetType() == typeof(TException))
                {
                    return true;
                }

                throw;
            }

            return false;
        }

        /// <summary>
        /// 個別のテスト結果を出力し、成功件数と失敗件数を集計する。
        /// </summary>
        /// <param name="passed">テストの成功判定</param>
        /// <param name="testName">テスト名</param>
        private void Check(bool passed, string testName)
        {
            if (passed)
            {
                // 成功件数を加算し、テスト結果を出力する。
                passedCount++;

                Debug.Log(
                    $"<color=#00CC66>【成功】</color> {testName}",
                    this);
            }
            else
            {
                // 失敗件数を加算し、エラーログを出力する。
                failedCount++;

                Debug.LogError(
                    $"【失敗】{testName}",
                    this);
            }
        }
    }
}
